/*
 * Generated by the /ship test coverage audit (pass 2).
 *
 * Value: protects=a stored Confluence page URL becomes an href only when it is plain http(s);
 *   fails_when=the scheme check is loosened or removed; why_new=no web test covers lib/confluence.ts;
 *   seam=none; no_claim=the API-side host pinning and rendering in a browser (pure function; unit only)
 */
import { safeConfluenceHref } from '../confluence';

jest.mock('@/lib/api', () => ({ authenticatedFetch: jest.fn() }));

describe('safeConfluenceHref', () => {
  it.each([
    'https://example.atlassian.net/wiki/spaces/SPACE/pages/1',
    'http://wiki.example.com/display/SPACE/Report',
    'HTTPS://example.atlassian.net/wiki/x',
  ])('keeps %s', (url) => {
    expect(safeConfluenceHref(url)).toBe(url);
  });

  it.each([
    ['javascript:', 'javascript:alert(1)'],
    ['protocol-relative', '//evil.example/x'],
    ['data:', 'data:text/html,<script>alert(1)</script>'],
    ['relative', '/wiki/spaces/SPACE'],
    ['empty', ''],
    ['null', null],
    ['undefined', undefined],
  ])('refuses a %s URL', (_label, url) => {
    expect(safeConfluenceHref(url)).toBeUndefined();
  });
});
